+      .sort((left, right) => compareCodePoints(left.projectId, right.projectId));
+    if (JSON.stringify(actual) !== JSON.stringify(review.identity.projects)) {
+      context.addIssue({ code: "custom", message: "The review identity must match every publishable draft." });
