import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import {
  validateUpload,
  registerMediaAsset,
  listMediaAssets,
  MediaValidationError,
} from "@/server/media/validate-upload";
import { getE2ESyntheticMediaAsset } from "@/server/media/manifest";

export const dynamic = "force-dynamic";
const privateHeaders = { "Cache-Control": "private, no-store, no-cache, must-revalidate", Pragma: "no-cache", Expires: "0", Vary: "Authorization, Cookie" };
function privateResponse(body: unknown, status = 200) { return Response.json(body, { status, headers: privateHeaders }); }
function privateAuthResponse(response: Response): Response {
  for (const [name, value] of Object.entries(privateHeaders)) response.headers.set(name, value);
  return response;
}

export async function GET(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
  const assets = await listMediaAssets();
  const fixture = getE2ESyntheticMediaAsset();
  if (fixture) assets.push(fixture);

  return privateResponse({ assets, authorizedActor: result.context.userId });
  } catch {
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }

}

export async function POST(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
    const contentType = request.headers.get("content-type") || "";

    let buffer: Uint8Array;
    let mime = "";
    let filename = "upload";

    if (contentType.includes("multipart/form-data")) {
      const formData = await request.formData();
      const file = formData.get("file") as File | null;
      if (!file) {
        return privateResponse({ error: "Missing file field in multipart form" }, 422);
      }
      buffer = new Uint8Array(await file.arrayBuffer());
      mime = file.type;
      filename = file.name;
    } else {
      // JSON base64 upload fallback
      const body = await request.json();
      if (!body.data || !body.mime) {
        return privateResponse({ error: "Missing data (base64) or mime in JSON payload" }, 422);
      }
      buffer = Buffer.from(body.data, "base64");
      mime = body.mime;
      filename = body.filename || "upload";
    }

    const validated = await validateUpload({ buffer, mime, filename });
    const asset = await registerMediaAsset(validated, result.context);

    return privateResponse({ success: true, action: "media_registered", asset, actor: result.context.userId }, 201);
  } catch (err) {
    if (err instanceof MediaValidationError) {
      return privateResponse({ error: err.message, code: err.code }, 422);
    }
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }
}

import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import { readApprovedDraftMediaBytes } from "@/server/media/manifest";

export const dynamic = "force-dynamic";
const privateHeaders = { "Cache-Control": "private, no-store, no-cache, must-revalidate", Pragma: "no-cache", Expires: "0", Vary: "Authorization, Cookie", "X-Content-Type-Options": "nosniff" };
function privateAuthResponse(response: Response): Response {
  for (const [name, value] of Object.entries(privateHeaders)) response.headers.set(name, value);
  return response;
}

export async function GET(request: Request, context: { params: Promise<{ id: string }> }) {
  const result = await verifyOwner(request);
  if (!result.ok) return privateAuthResponse(createAuthErrorResponse(result));
  const { id } = await context.params;
  if (!id || id.length > 200 || id.includes("/")) {
    return new Response(null, { status: 404, headers: privateHeaders });
  }
  try {
    const media = await readApprovedDraftMediaBytes(id, result.context);
    if (!media) return new Response(null, { status: 404, headers: privateHeaders });
    return new Response(media.bytes.slice().buffer as ArrayBuffer, {
      status: 200,
      headers: {
        ...privateHeaders,
        "Content-Type": media.mime,
        "Content-Length": String(media.bytes.byteLength),
      },
    });
  } catch {
    return new Response(null, { status: 503, headers: privateHeaders });
  }
}

import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import { generateDraftReview } from "@/server/content/preview";
import { ProjectIdSchema } from "@/contracts/content";

export const dynamic = "force-dynamic";
const privateHeaders = { "Cache-Control": "private, no-store, no-cache, must-revalidate", Pragma: "no-cache", Expires: "0", Vary: "Authorization, Cookie" };
function privateResponse(body: unknown, status = 200) { return Response.json(body, { status, headers: privateHeaders }); }
function privateAuthResponse(response: Response): Response {
  for (const [name, value] of Object.entries(privateHeaders)) response.headers.set(name, value);
  return response;
}

export async function GET(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) return privateAuthResponse(createAuthErrorResponse(result));
  const rawProjectId = new URL(request.url).searchParams.get("projectId");
  const projectId = rawProjectId === null ? null : ProjectIdSchema.safeParse(rawProjectId);
  if (projectId !== null && !projectId.success) return privateResponse({ error: "Invalid project ID." }, 422);
  try {
    const review = await generateDraftReview(result.context, undefined, projectId?.data ?? null);
    if (projectId && !review.drafts.some((draft) => draft.projectId === projectId.data)) {
      return privateResponse({ error: "Draft not found." }, 404);
    }
    return privateResponse({ review, authorizedActor: result.context.userId });
  } catch {
    return privateResponse({ error: "Private review is temporarily unavailable." }, 503);
  }
}

import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import {
  listProjectDrafts,
  saveProjectDraft,
  RevisionConflictError,
  ContentValidationError,
} from "@/server/content/revisions";
import { ProjectIdSchema, PublishedProjectSchema } from "@/contracts/content";
import { z } from "zod";
import { MediaValidationError } from "@/server/media/validate-upload";

export const dynamic = "force-dynamic";
const privateHeaders = { "Cache-Control": "private, no-store, no-cache, must-revalidate", Pragma: "no-cache", Expires: "0", Vary: "Authorization, Cookie" };
const saveBodySchema = z.strictObject({
  projectId: ProjectIdSchema,
  expectedRevision: z.number().int().positive().safe(),
  project: PublishedProjectSchema,
});

function privateResponse(body: unknown, status = 200) {
  return Response.json(body, { status, headers: privateHeaders });
}

function privateAuthResponse(response: Response): Response {
  for (const [name, value] of Object.entries(privateHeaders)) response.headers.set(name, value);
  return response;
}

export async function GET(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
  const drafts = await listProjectDrafts(result.context);
  const projects = drafts
    .filter((d) => d.projectId !== "candidatex")
    .map((d) => ({
      id: d.projectId,
      slug: d.project.slug,
      title: d.project.title,
      draftRevision: d.draftRevision,
    }));

  return privateResponse(
    {
      projects,
      drafts,
      authorizedActor: result.context.userId,
    }
  );
  } catch {
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }

}

export async function POST(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
    const parsed = saveBodySchema.safeParse(await request.json().catch(() => null));
    if (!parsed.success) return privateResponse({ error: "projectId, positive expectedRevision and a complete project are required." }, 422);
    const { revision: _revision, ...project } = parsed.data.project;
    void _revision;
    const saved = await saveProjectDraft({ projectId: parsed.data.projectId, expectedRevision: parsed.data.expectedRevision, project }, result.context);
    return privateResponse({ success: true, action: "draft_saved", draftRevision: saved.draftRevision, project: saved.project, actor: result.context.userId }, 201);
  } catch (err) {
    if (err instanceof RevisionConflictError) {
      return privateResponse({ error: err.message, code: err.code }, err.status);
    }
    if (err instanceof ContentValidationError || err instanceof MediaValidationError) {
      return privateResponse({ error: err.message, code: err.code }, err.status);
    }
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }
}

import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import {
  publishRevision,
  readPublicPublication,
  readPublicationHistory,
} from "@/server/content/publish";
import { RevisionConflictError, ContentValidationError } from "@/server/content/revisions";
import { MediaValidationError } from "@/server/media/validate-upload";
import { ReviewIdentitySchema } from "@/server/content/preview";
import { z } from "zod";

export const dynamic = "force-dynamic";
const privateHeaders = { "Cache-Control": "private, no-store, no-cache, must-revalidate", Pragma: "no-cache", Expires: "0", Vary: "Authorization, Cookie" };
const publishBodySchema = z.strictObject({ expectedRevision: z.number().int().positive().safe(), review: ReviewIdentitySchema });
function privateResponse(body: unknown, status = 200) { return Response.json(body, { status, headers: privateHeaders }); }
function privateAuthResponse(response: Response): Response {
  for (const [name, value] of Object.entries(privateHeaders)) response.headers.set(name, value);
  return response;
}

export async function GET(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
  const active = await readPublicPublication();
  if (!active) return privateResponse({ error: "Publication storage is unavailable." }, 503);
  const history = await readPublicationHistory();

  return privateResponse({ currentRevision: active.revision, activePublication: active, history, authorizedActor: result.context.userId });
  } catch {
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }

}

export async function POST(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
    const parsed = publishBodySchema.safeParse(await request.json().catch(() => null));
    if (!parsed.success) return privateResponse({ error: "A positive expectedRevision and complete current review are required." }, 422);

    const publication = await publishRevision(
      {
        expectedRevision: parsed.data.expectedRevision,
        review: parsed.data.review,
      },
      result.context
    );

    return privateResponse({ success: true, action: "publication_published", publication, actor: result.context.userId });
  } catch (err) {
    if (err instanceof RevisionConflictError) {
      return privateResponse({ error: err.message, code: err.code }, 409);
    }
    if (err instanceof ContentValidationError || err instanceof MediaValidationError) {
      return privateResponse({ error: err.message, code: "UNPROCESSABLE_ENTITY" }, 422);
    }
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }
}

import { verifyOwner, createAuthErrorResponse } from "@/server/auth/require-owner";
import { rollbackPublication } from "@/server/content/publish";
import { ContentValidationError, RevisionConflictError } from "@/server/content/revisions";
import { MediaValidationError } from "@/server/media/validate-upload";
import { z } from "zod";

export const dynamic = "force-dynamic";
const privateHeaders = { "Cache-Control": "private, no-store, no-cache, must-revalidate", Pragma: "no-cache", Expires: "0", Vary: "Authorization, Cookie" };
const rollbackBodySchema = z.strictObject({ targetRevision: z.number().int().positive().safe(), expectedRevision: z.number().int().positive().safe(), reason: z.string().trim().min(1).max(500) });
function privateResponse(body: unknown, status = 200) { return Response.json(body, { status, headers: privateHeaders }); }
function privateAuthResponse(response: Response): Response {
  for (const [name, value] of Object.entries(privateHeaders)) response.headers.set(name, value);
  return response;
}

export async function POST(request: Request) {
  const result = await verifyOwner(request);
  if (!result.ok) {
    return privateAuthResponse(createAuthErrorResponse(result));
  }

  try {
    const parsed = rollbackBodySchema.safeParse(await request.json().catch(() => null));
    if (!parsed.success) return privateResponse({ error: "targetRevision, expectedRevision and a rollback reason of 1-500 characters are required." }, 422);

    const publication = await rollbackPublication(parsed.data.targetRevision, parsed.data.expectedRevision, parsed.data.reason, result.context);

    return privateResponse({ success: true, action: "publication_rollback", publication, actor: result.context.userId, reason: parsed.data.reason.trim() });
  } catch (err) {
    if (err instanceof RevisionConflictError) return privateResponse({ error: err.message, code: err.code }, 409);
    if (err instanceof ContentValidationError || err instanceof MediaValidationError) {
      return privateResponse({ error: err.message, code: "UNPROCESSABLE_ENTITY" }, 422);
    }
    return privateResponse({ error: "Private storage is temporarily unavailable." }, 503);
  }
}

