      <div className={styles.sectionBox}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><h2>External links ({currentProject.links.length})</h2><button type="button" onClick={addLink} className={styles.buttonSecondary}>Add link</button></div>
        {currentProject.links.map((link, index) => <div key={`${index}-${link.label}`} style={{ display: "flex", gap: "0.75rem", marginBottom: "0.75rem", flexWrap: "wrap" }}>
          <input aria-label={`Link ${index + 1} label`} value={link.label} onChange={(event) => updateLink(index, "label", event.target.value)} className={styles.input} />
          <input aria-label={`Link ${index + 1} URL`} type="url" value={link.url} onChange={(event) => updateLink(index, "url", event.target.value)} className={styles.input} />
          <button type="button" onClick={() => updateProject("links", currentProject.links.filter((_, itemIndex) => itemIndex !== index))} className={styles.buttonDanger}>Remove</button>
        </div>)}
      </div>

      <div className={styles.sectionBox}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><h2>Evidence records ({currentProject.evidence.length})</h2><button type="button" onClick={addEvidence} className={styles.buttonSecondary}>Add evidence</button></div>
        {currentProject.evidence.map((item, index) => <div key={`${index}-${item.id}`} style={{ display: "grid", gap: "0.5rem", border: "1px solid var(--color-line)", padding: "0.75rem", borderRadius: 6, marginBottom: "0.75rem" }}>
          <input aria-label={`Evidence ${index + 1} ID`} value={item.id} onChange={(event) => updateEvidence(index, "id", event.target.value)} className={styles.input} />
          <select aria-label={`Evidence ${index + 1} kind`} value={item.kind} onChange={(event) => updateEvidence(index, "kind", event.target.value as EvidenceRef["kind"])} className={styles.input}>
            <option value="repository">repository</option><option value="deployment">deployment</option><option value="measurement">measurement</option><option value="document">document</option>
          </select>
          <input aria-label={`Evidence ${index + 1} URL`} type="url" placeholder="https://…" value={item.url ?? ""} onChange={(event) => updateEvidence(index, "url", event.target.value || null)} className={styles.input} />
          <select aria-label={`Evidence ${index + 1} status`} value={item.status} onChange={(event) => updateEvidence(index, "status", event.target.value as EvidenceStatus)} className={styles.input}>
            <option value="unknown">unknown</option><option value="verified">verified</option><option value="not-measured">not-measured</option><option value="not-applicable">not-applicable</option>
          </select>
          <textarea aria-label={`Evidence ${index + 1} note`} placeholder="Evidence note" value={item.note} onChange={(event) => updateEvidence(index, "note", event.target.value)} className={styles.input} rows={2} />
          <button type="button" onClick={() => updateProject("evidence", currentProject.evidence.filter((_, itemIndex) => itemIndex !== index))} className={styles.buttonDanger}>Remove evidence</button>
        </div>)}
      </div>

      <div className={styles.actionRow}>
        <button type="button" onClick={discardUnsavedChanges} disabled={saving} className={styles.buttonSecondary}>Discard unsaved changes</button>
        <button type="button" onClick={saveDraft} disabled={saving} className={styles.button} style={{ width: "auto", minWidth: 200 }}>{saving ? "Saving draft…" : "Save draft revision"}</button>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { ProjectId, Publication } from "@/contracts/content";
import styles from "@/app/admin/admin.module.css";

interface PrivateDraftReview {
  identity: {
    expectedPublicationRevision: number;
    projects: Array<{ projectId: ProjectId; draftRevision: number }>;
    siteDraftRevision: null;
    media: unknown[];
    candidateSha256: string;
  };
  checks: Array<{
    scope: "project";
    id: ProjectId;
    kind: "schema" | "evidence-records" | "https-links" | "approved-media" | "publication-rules";
    status: "passed" | "failed";
    checkedAt: string;
    reasons: string[];
  }>;
  canPublish: boolean;
}

export interface HistoryItem {
  revision: number;
  actor: string;
  publishedAt: string;
  action: "publish" | "rollback";
  targetRevision?: number;
  rollbackReason?: string;
}

interface PublishReviewProps {
  initialPublication: Publication;
  initialHistory: HistoryItem[];
  initialReview: PrivateDraftReview;
}

interface ApiResult { publication?: Publication & { cacheRefreshed?: boolean; cacheRefreshWarning?: string }; history?: HistoryItem[]; review?: PrivateDraftReview; actor?: string; error?: string; }

async function requestJson(path: string): Promise<ApiResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 10_000);
  try {
    const response = await fetch(path, { cache: "no-store", signal: controller.signal });
    const data = await response.json().catch(() => null) as ApiResult | null;
    if (!response.ok || !data) throw new Error(data?.error || `Refresh failed (${response.status}).`);
    return data;
  } finally { clearTimeout(timer); }
}

async function postJson(path: string, body: unknown): Promise<{ data: ApiResult; status: number }> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 10_000);
  try {
    const response = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body), signal: controller.signal });
    const data = await response.json().catch(() => null) as ApiResult | null;
    if (!data) throw new Error(`Request failed (${response.status}) with an invalid response.`);
    return { data, status: response.status };
  } finally { clearTimeout(timer); }
}

export function PublishReview({ initialPublication, initialHistory, initialReview }: PublishReviewProps) {
  const [publication, setPublication] = useState(initialPublication);
  const [history, setHistory] = useState(initialHistory);
  const [review, setReview] = useState(initialReview);
  const [expectedRevision, setExpectedRevision] = useState(initialPublication.revision);
  const [feedback, setFeedback] = useState<{ type: "success" | "error" | "warning"; message: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  async function refreshAfterCommit(successMessage: string) {
    try {
      const [reviewResponse, publicationResponse] = await Promise.all([
        requestJson("/api/admin/preview"),
        requestJson("/api/admin/publish"),
      ]);
      if (!reviewResponse.review || !publicationResponse.publication || !publicationResponse.history) throw new Error("The refreshed review response was incomplete.");
      setReview(reviewResponse.review);
      setPublication(publicationResponse.publication);
      setHistory(publicationResponse.history);
      setExpectedRevision(publicationResponse.publication.revision);
      setFeedback({ type: "success", message: `${successMessage} Review refreshed. CDN/edge not observed.` });
    } catch (error) {
      setFeedback({ type: "success", message: `${successMessage} The change committed, but the follow-up review could not be refreshed${error instanceof Error ? `: ${error.message}` : "."} CDN/edge not observed.` });
    }
  }

  async function refreshReview() {
    setRefreshing(true);
    setFeedback(null);
    try {
      const [reviewResponse, publicationResponse] = await Promise.all([
        requestJson("/api/admin/preview"),
        requestJson("/api/admin/publish"),
      ]);
      if (!reviewResponse.review || !publicationResponse.publication || !publicationResponse.history) throw new Error("The refreshed review response was incomplete.");
      setReview(reviewResponse.review);
      setPublication(publicationResponse.publication);
      setHistory(publicationResponse.history);
      setExpectedRevision(publicationResponse.publication.revision);
      setFeedback({ type: "success", message: "Current draft review and publication state loaded. CDN/edge not observed." });
    } catch (error) {
      setFeedback({ type: "error", message: error instanceof Error ? error.message : "Could not refresh the review." });
    } finally { setRefreshing(false); }
  }

  async function handlePublish() {
    setBusy(true);
    setFeedback(null);
    try {
      const { data, status } = await postJson("/api/admin/publish", { expectedRevision, review: review.identity });
      if (status === 409) throw new Error(`Stale revision conflict (409): ${data.error || "Refresh the review before publishing."}`);
      if (status === 422) throw new Error(`Validation failed (422): ${data.error || "The reviewed candidate is not publishable."}`);
      if (status >= 400 || !data.publication) throw new Error(data.error || `Publication failed (${status}).`);
      const next = data.publication;
      setPublication(next);
      setExpectedRevision(next.revision);
      setHistory((current) => [...current, { revision: next.revision, actor: data.actor || "owner", publishedAt: next.publishedAt, action: "publish" }]);
      const cacheMessage = next.cacheRefreshWarning ? ` Application cache refresh reported: ${next.cacheRefreshWarning}.` : "";
      await refreshAfterCommit(`Publication revision ${next.revision} committed.${cacheMessage}`);
    } catch (error) {
      setFeedback({ type: "error", message: error instanceof Error ? error.message : "Network error publishing the reviewed revision." });
    } finally { setBusy(false); }
  }

  async function handleRollback(targetRevision: number) {
    const reason = window.prompt(`Reason for rolling back to publication revision ${targetRevision} (required):`)?.trim() ?? "";
    if (!reason) return;
    setBusy(true);
    setFeedback(null);
    try {
      const { data, status } = await postJson("/api/admin/rollback", { targetRevision, expectedRevision, reason });
      if (status === 409) throw new Error(`Stale revision conflict (409): ${data.error || "Refresh publication state before rollback."}`);
      if (status === 422) throw new Error(`Rollback rejected (422): ${data.error || "The target snapshot is not valid."}`);
      if (status >= 400 || !data.publication) throw new Error(data.error || `Rollback failed (${status}).`);
      const next = data.publication;
      setPublication(next);
      setExpectedRevision(next.revision);
      setHistory((current) => [...current, { revision: next.revision, actor: data.actor || "owner", publishedAt: next.publishedAt, action: "rollback", targetRevision, rollbackReason: reason }]);
      const cacheMessage = next.cacheRefreshWarning ? ` Application cache refresh reported: ${next.cacheRefreshWarning}.` : "";
      await refreshAfterCommit(`Rollback to revision ${targetRevision} committed as revision ${next.revision}.${cacheMessage}`);
    } catch (error) {
      setFeedback({ type: "error", message: error instanceof Error ? error.message : "Network error performing rollback." });
    } finally { setBusy(false); }
  }

  const publishChecksPassed = review.checks.every((check) => check.status === "passed");
  const identityMatches = expectedRevision === review.identity.expectedPublicationRevision;

  return (
    <div style={{ marginTop: "1.5rem" }}>
      <div className={styles.grid}>
        <section className={styles.card}>
          <h2>Active publication</h2>
          <p>Revision <strong>r{publication.revision}</strong> · {new Date(publication.publishedAt).toLocaleString()}</p>
          <p>{publication.projects.length} published projects</p>
        </section>
        <section className={styles.card}>
          <h2>Reviewed draft</h2>
          <p>Expected publication revision: r{review.identity.expectedPublicationRevision}</p>
          <p>{review.identity.projects.length} publishable drafts · {review.identity.media.length} media identities</p>
          <p>Candidate hash: <code>{review.identity.candidateSha256}</code></p>
        </section>
        <section className={styles.card}>
          <h2>Review status</h2>
          <p>{review.canPublish ? "All publish checks passed." : "This candidate cannot be published yet."}</p>
          <p>{review.checks.filter((check) => check.status === "passed").length} passed · {review.checks.filter((check) => check.status === "failed").length} failed</p>
        </section>
      </div>

      {feedback && <div role="status" className={`${styles.feedbackBox} ${feedback.type === "success" ? styles.feedbackSuccess : feedback.type === "warning" ? styles.feedbackWarning : styles.feedbackError}`}>{feedback.message}</div>}

      <section className={styles.sectionBox}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "1rem", flexWrap: "wrap" }}>
          <h2>Project preflight checks</h2>
          <button type="button" onClick={refreshReview} disabled={busy || refreshing} className={styles.buttonSecondary}>{refreshing ? "Refreshing…" : "Refresh review"}</button>
        </div>
        <ul style={{ paddingLeft: "1.25rem" }}>
          {review.checks.map((check) => <li key={`${check.id}-${check.kind}`}>
            <strong>{check.id} / {check.kind}:</strong> {check.status} · checked {new Date(check.checkedAt).toLocaleString()}
            {check.reasons.length > 0 && <ul>{check.reasons.map((reason, index) => <li key={`${check.id}-${check.kind}-${index}`}>{reason}</li>)}</ul>}
          </li>)}
        </ul>
        <p>HTTPS checks validate recorded URL syntax only. This review does not fetch external links or reverify their contents.</p>
        <p>CandidateX remains a private draft. CDN/edge state is not observed by this review.</p>
      </section>

      <section className={styles.sectionBox}>
        <h2>Publish reviewed candidate</h2>
        <p>Publishing uses the current review identity and expected publication revision. A stale review must be refreshed.</p>
        <label htmlFor="pub-expected-rev" className={styles.label}>Expected publication revision</label>
        <input id="pub-expected-rev" type="number" min={1} value={expectedRevision} onChange={(event) => setExpectedRevision(Number(event.target.value))} className={styles.input} style={{ maxWidth: 140 }} />
        <button type="button" onClick={handlePublish} disabled={busy || !review.canPublish || !publishChecksPassed || !identityMatches} className={styles.button}>
          {busy ? "Applying…" : `Publish candidate r${expectedRevision}`}
        </button>
        {!identityMatches && <p role="alert">The expected revision differs from the reviewed identity. Refresh review to continue.</p>}
      </section>

      <section className={styles.sectionBox}>
        <h2>Publication history and rollback</h2>
        <p>Rollback creates a new publication revision and records the supplied reason.</p>
        <table className={styles.table}>
          <thead><tr><th>Revision</th><th>Action</th><th>Published</th><th>Actor</th><th>Reason</th><th>Rollback</th></tr></thead>
          <tbody>{history.slice().reverse().map((item) => <tr key={item.revision}>
            <td>r{item.revision}{item.revision === publication.revision ? " · Active" : ""}</td>
            <td>{item.action === "rollback" ? `Rollback to r${item.targetRevision}` : "Publish"}</td>
            <td>{new Date(item.publishedAt).toLocaleString()}</td>
            <td><code>{item.actor}</code></td>
            <td>{item.rollbackReason ?? "—"}</td>
            <td>{item.revision !== publication.revision ? <button type="button" onClick={() => handleRollback(item.revision)} disabled={busy} className={styles.buttonSecondary}>Rollback to r{item.revision}</button> : "Current snapshot"}</td>
          </tr>)}</tbody>
        </table>
      </section>
    </div>
  );
}

"use client";

import type { ContentSection } from "@/contracts/content";
import styles from "@/app/admin/admin.module.css";

type ContentBlock = ContentSection["blocks"][number];
export interface MediaChoice {
  id: string;
  mime: string;
  bytes: number;
  approvalStatus: "pending" | "approved" | "rejected";
}

interface StructuredBlockEditorProps {
  section: ContentSection;
  sectionIndex: number;
  mediaAssets: MediaChoice[];
  onChange: (section: ContentSection) => void;
  onMoveSection: (delta: -1 | 1) => void;
  canMoveUp: boolean;
  canMoveDown: boolean;
}

function blockLabel(block: ContentBlock): string {
  switch (block.type) {
    case "paragraph": case "code": return block.text.slice(0, 70);
    case "list": return `${block.items.length} list items`;
    case "image": return `Image ${block.mediaId}`;
  }
}

export function StructuredBlockEditor({ section, sectionIndex, mediaAssets, onChange, onMoveSection, canMoveUp, canMoveDown }: StructuredBlockEditorProps) {
  const approvedAssets = mediaAssets.filter((asset) => asset.approvalStatus === "approved");
  const setBlocks = (blocks: ContentBlock[]) => onChange({ ...section, blocks });

  function updateBlock(index: number, block: ContentBlock) {
    setBlocks(section.blocks.map((current, currentIndex) => currentIndex === index ? block : current));
  }

  function addBlock(type: ContentBlock["type"]) {
    let block: ContentBlock;
    switch (type) {
      case "paragraph": block = { type, text: "New paragraph." }; break;
      case "list": block = { type, items: ["New list item"] }; break;
      case "code": block = { type, language: "text", text: "" }; break;
      case "image": {
        const asset = approvedAssets[0];
        if (!asset) return;
        block = { type, mediaId: asset.id, alt: "", caption: "" };
        break;
      }
    }
    setBlocks([...section.blocks, block]);
  }

  function moveBlock(index: number, delta: -1 | 1) {
    const target = index + delta;
    if (target < 0 || target >= section.blocks.length) return;
    const next = [...section.blocks];
    [next[index], next[target]] = [next[target]!, next[index]!];
    setBlocks(next);
    requestAnimationFrame(() => document.getElementById(`section-${section.id}-block-${target}`)?.focus());
  }

  function removeBlock(index: number) {
    if (section.blocks.length === 1) return;
    const next = section.blocks.filter((_, itemIndex) => itemIndex !== index);
    setBlocks(next);
    const focusIndex = Math.min(index, next.length - 1);
    requestAnimationFrame(() => {
      const target = document.getElementById(`section-${section.id}-block-${focusIndex}`) ?? document.getElementById(`section-heading-${section.id}`);
      target?.focus();
    });
  }

  function updateListItem(blockIndex: number, itemIndex: number, value: string) {
    const block = section.blocks[blockIndex];
    if (block?.type !== "list") return;
    updateBlock(blockIndex, { ...block, items: block.items.map((item, index) => index === itemIndex ? value : item) });
  }

  function moveListItem(blockIndex: number, itemIndex: number, delta: -1 | 1) {
    const block = section.blocks[blockIndex];
    if (block?.type !== "list") return;
    const targetIndex = itemIndex + delta;
    if (targetIndex < 0 || targetIndex >= block.items.length) return;
    const items = [...block.items];
    [items[itemIndex], items[targetIndex]] = [items[targetIndex]!, items[itemIndex]!];
    updateBlock(blockIndex, { ...block, items });
    requestAnimationFrame(() => document.getElementById(`list-item-${section.id}-${blockIndex}-${targetIndex}`)?.focus());
  }

  function removeListItem(blockIndex: number, itemIndex: number) {
    const block = section.blocks[blockIndex];
    if (block?.type !== "list" || block.items.length === 1) return;
    const items = block.items.filter((_, index) => index !== itemIndex);
    updateBlock(blockIndex, { ...block, items });
    const focusIndex = Math.min(itemIndex, items.length - 1);
    requestAnimationFrame(() => document.getElementById(`list-item-${section.id}-${blockIndex}-${focusIndex}`)?.focus());
  }

  function addListItem(blockIndex: number) {
    const block = section.blocks[blockIndex];
    if (block?.type !== "list") return;
    updateBlock(blockIndex, { ...block, items: [...block.items, "New list item"] });
    requestAnimationFrame(() => document.getElementById(`list-item-${section.id}-${blockIndex}-${block.items.length}`)?.focus());
  }

  return (
    <section className={styles.sectionBox} aria-label={`Section ${sectionIndex + 1} content`}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "0.75rem", flexWrap: "wrap" }}>
        <label className={styles.label} htmlFor={`section-heading-${section.id}`}>Section {sectionIndex + 1}</label>
        <div style={{ display: "flex", gap: "0.5rem" }}>
          <button type="button" className={styles.buttonSecondary} disabled={!canMoveUp} onClick={() => onMoveSection(-1)} aria-label={`Move section ${sectionIndex + 1} up`}>Move up</button>
          <button type="button" className={styles.buttonSecondary} disabled={!canMoveDown} onClick={() => onMoveSection(1)} aria-label={`Move section ${sectionIndex + 1} down`}>Move down</button>
        </div>
      </div>
      <input id={`section-heading-${section.id}`} aria-label={`Section ${sectionIndex + 1} heading`} className={styles.input} value={section.heading} onChange={(event) => onChange({ ...section, heading: event.target.value })} />

      <div style={{ display: "grid", gap: "0.75rem", marginTop: "0.75rem" }}>
        {section.blocks.map((block, index) => (
          <article id={`section-${section.id}-block-${index}`} key={`${section.id}-${index}`} tabIndex={-1} style={{ border: "1px solid var(--color-line)", borderRadius: 6, padding: "0.75rem" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.5rem", flexWrap: "wrap" }}>
              <strong>Block {index + 1}: {block.type}</strong>
              <div style={{ display: "flex", gap: "0.4rem" }}>
                <button type="button" className={styles.buttonSecondary} disabled={index === 0} onClick={() => moveBlock(index, -1)} aria-label={`Move block ${index + 1} up`}>Up</button>
                <button type="button" className={styles.buttonSecondary} disabled={index === section.blocks.length - 1} onClick={() => moveBlock(index, 1)} aria-label={`Move block ${index + 1} down`}>Down</button>
                <button type="button" className={styles.buttonDanger} disabled={section.blocks.length === 1} onClick={() => removeBlock(index)} aria-label={`Remove block ${index + 1}`}>Remove</button>
              </div>
            </div>
            <p className={styles.subtitle}>{blockLabel(block)}</p>
            {block.type === "paragraph" && <textarea className={styles.input} aria-label={`Paragraph block ${index + 1}`} rows={4} value={block.text} onChange={(event) => updateBlock(index, { ...block, text: event.target.value })} />}
            {block.type === "code" && <>
              <input className={styles.input} aria-label={`Code language block ${index + 1}`} value={block.language} onChange={(event) => updateBlock(index, { ...block, language: event.target.value })} />
              <textarea className={styles.input} aria-label={`Code text block ${index + 1}`} rows={6} value={block.text} onChange={(event) => updateBlock(index, { ...block, text: event.target.value })} />
            </>}
            {block.type === "list" && <div style={{ display: "grid", gap: "0.5rem" }}>
              {block.items.map((item, itemIndex) => <div key={`${section.id}-${index}-${itemIndex}`} style={{ display: "flex", gap: "0.4rem", flexWrap: "wrap" }}>
                <input id={`list-item-${section.id}-${index}-${itemIndex}`} className={styles.input} aria-label={`List block ${index + 1} item ${itemIndex + 1}`} value={item} onChange={(event) => updateListItem(index, itemIndex, event.target.value)} />
                <button type="button" className={styles.buttonSecondary} disabled={itemIndex === 0} onClick={() => moveListItem(index, itemIndex, -1)} aria-label={`Move list item ${itemIndex + 1} up`}>Up</button>
                <button type="button" className={styles.buttonSecondary} disabled={itemIndex === block.items.length - 1} onClick={() => moveListItem(index, itemIndex, 1)} aria-label={`Move list item ${itemIndex + 1} down`}>Down</button>
                <button type="button" className={styles.buttonDanger} disabled={block.items.length === 1} onClick={() => removeListItem(index, itemIndex)} aria-label={`Remove list item ${itemIndex + 1}`}>Remove item</button>
              </div>)}
              <button type="button" className={styles.buttonSecondary} onClick={() => addListItem(index)}>Add list item to block {index + 1}</button>
            </div>}
            {block.type === "image" && <div style={{ display: "grid", gap: "0.5rem" }}>
              <label className={styles.label} htmlFor={`media-${section.id}-${index}`}>Approved media</label>
              <select id={`media-${section.id}-${index}`} className={styles.input} value={block.mediaId} onChange={(event) => updateBlock(index, { ...block, mediaId: event.target.value })}>
                {!approvedAssets.some((asset) => asset.id === block.mediaId) && <option value={block.mediaId} disabled>Current media is not approved or unavailable</option>}
                {approvedAssets.map((asset) => <option key={asset.id} value={asset.id}>{asset.id}{asset.id === "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee" ? " · synthetic local browser fixture; not provider approval" : ""} ({asset.mime}, {asset.bytes} bytes)</option>)}
              </select>
              <input className={styles.input} aria-label={`Image alt text block ${index + 1}`} placeholder="Alternative text" value={block.alt} onChange={(event) => updateBlock(index, { ...block, alt: event.target.value })} />
              <input className={styles.input} aria-label={`Image caption block ${index + 1}`} placeholder="Caption" value={block.caption} onChange={(event) => updateBlock(index, { ...block, caption: event.target.value })} />
            </div>}
          </article>
        ))}
      </div>

      <div style={{ display: "flex", gap: "0.5rem", flexWrap: "wrap", marginTop: "0.75rem" }}>
        <button type="button" className={styles.buttonSecondary} onClick={() => addBlock("paragraph")}>Add paragraph</button>
        <button type="button" className={styles.buttonSecondary} onClick={() => addBlock("list")}>Add list</button>
        <button type="button" className={styles.buttonSecondary} onClick={() => addBlock("code")}>Add code</button>
        <button type="button" className={styles.buttonSecondary} disabled={approvedAssets.length === 0} onClick={() => addBlock("image")}>Add approved image</button>
      </div>
    </section>
  );
}

