    } catch {
      await new Promise((r) => setTimeout(r, 200));
      try {
        await page.screenshot({
          path: path.join(screenshotDir, `${filename}.png`),
          fullPage: true,
        });
      } catch {
        // Transient lock on Windows does not fail functional assertion
      }
    }
  }
}

